'use strict';
const lessons=[
{id:'branches',name:'A world of your own',topic:'THE BIG IDEA',title:'One database.<br><em>Room to experiment.</em>',intro:'Try a risky change. Keep the original. Forklift gives every experiment its own PostgreSQL cluster, so curiosity doesn’t have to come with consequences.',time:'5 MIN',lab:'Make a change. Watch what stays the same.',question:'You delete rows in a branch. What happens to its checkpoint?',answers:['It loses the same rows.','It keeps its original contents.','It disappears when the branch stops.'],correct:1,explanation:'A checkpoint is immutable saved state. The branch is a separate writable cluster. Changes in the branch do not flow back into the checkpoint.'},
{id:'queries',name:'From rows to results'}, {id:'transactions',name:'A promise to your data'}, {id:'cow',name:'Copy less, share more'}, {id:'objects',name:'A recipe for a database'}, {id:'lifecycle',name:'Park it. Start it. Keep it.'}, {id:'recovery',name:'What if it crashes?'}, {id:'code',name:'Inside the Rust'}, {id:'evidence',name:'What we actually know'}];
let completed={};try{completed=JSON.parse(localStorage.getItem('forklift-field-guide-v1')||'{}')}catch{}
if(!completed||typeof completed!=='object'||Array.isArray(completed))completed={};
let current=0,branchDeleted=false;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function quiz(l){return `<section class="check"><span class="overline">CHECK YOUR MENTAL MODEL</span><h3>${l.question}</h3><div class="answers">${l.answers.map((a,i)=>`<button data-answer="${i}">${String.fromCharCode(65+i)} &nbsp; ${a}</button>`).join('')}</div><div class="answer-feedback" role="status"></div></section>`}
function render(){current=Math.max(0,lessons.findIndex(l=>l.id===location.hash.slice(1)));const l=lessons[current];$('#chapters').innerHTML=lessons.map((x,i)=>`<a href="#${x.id}" class="${i===current?'active':''}" ${i===current?'aria-current="page"':''}><span class="num">${completed[x.id]?'✓':String(i+1).padStart(2,'0')}</span>${x.name}</a>`).join('');updateProgress();$('#content').innerHTML=`<div class="eyebrow">${String(current+1).padStart(2,'0')} / ${l.topic||'FIELD NOTES'}</div><h1>${l.title||l.name}</h1><p class="lead">${l.intro||'This lesson is being assembled.'}</p><div class="lesson-meta"><span class="pill dark">${l.time||'5 MIN'} LESSON</span><span class="pill">EXPLAIN · EXPERIMENT · REFLECT</span></div><div id="lesson-body">${lessonBody(l.id)}</div>${l.question?quiz(l):''}<div class="next-row"><span>${current+1} of ${lessons.length} · Go at your own pace</span><a href="#${lessons[(current+1)%lessons.length].id}">${current===lessons.length-1?'Back to the beginning':'Next: '+lessons[current+1].name}</a></div>`;bind(l.id);document.title=l.name+' — Forklift Field Guide'}
function updateProgress(){const n=lessons.filter(l=>completed[l.id]).length;$('#progress').value=n;$('#progress-label').textContent=`${n} / ${lessons.length}`}
function lab(title,body,label='INTERACTIVE MODEL'){return `<section class="lab"><div class="lab-top"><span>${title}</span><span>${label}</span></div>${body}</section>`}
function source(path,label=path){return `<a href="reader.html?file=${encodeURIComponent(path)}" target="_blank" rel="noopener">${label}</a>`}
function lessonBody(id){if(id==='branches')return lab('01 / THE BRANCH SANDBOX',`<div class="controls"><button class="primary" id="delete-rows">Delete 10% in branch 03</button><button id="reset-branch" disabled>Reset branch 03</button></div><div class="root-node">checkpoint / seed<small>1,000 rows · immutable</small></div><div class="branch-lines"></div><div class="branch-grid">${['add-index','change-schema','delete-rows'].map((n,i)=>`<div class="branch-card" id="branch-${i}"><span class="tag">experiment ${String(i+1).padStart(2,'0')}</span><strong>${n}</strong><div class="row-count" id="rows-${i}">1,000</div><small>account rows</small><div class="mini-rows">${'<i></i>'.repeat(10)}</div><small id="branch-caption-${i}">Independent writable files</small></div>`).join('')}</div><div class="feedback" id="branch-feedback" role="status">Predict first: if you delete 100 rows in experiment 03, which other counts will change?</div><small class="muted">A browser simulation with 1,000 illustrative rows. No real database is connected.</small>`)+`<section class="two-col prose"><div><h2>A branch is a whole world.</h2><p>Here, a <strong>cluster</strong> means one PostgreSQL server’s collection of databases and supporting files. It does not mean a group of machines. A running branch has its own server and connection endpoint.</p><p>Each experiment starts from saved state, then evolves independently. A schema change, an index, or a deletion belongs only to the branch where you made it.</p></div><div class="callout"><span class="overline">THE DIVISION OF LABOR</span><h3>Postgres does the database.<br>Forklift handles the lifecycle.</h3><p>PostgreSQL executes SQL, plans queries, checks constraints, and manages transactions. Forklift manages files, named branches, checkpoints, and server processes.</p></div></section><section class="prose"><h2>Why build this?</h2><p>Suppose you want to try an index, migrate a schema, and let an agent edit data. Manually juggling copied directories, sockets, process IDs, and recovery is error-prone. Forklift makes those experiments named, isolated, and repeatable on your own Mac.</p><p>The Git analogy helps: checkpoints are saved states, branches are workspaces, and reset returns to a saved state. <strong>There is no branch merge.</strong> Reconciling conflicting database rows, schemas, and application meaning is a separate problem.</p></section><div class="source-links">${source('README.md','Project overview')}${source('docs/architecture-decision.md','Why this architecture')}</div>`;return renderLesson(id)}
function bind(id){if(id==='branches'){branchDeleted=false;$('#delete-rows').onclick=()=>changeBranch(true);$('#reset-branch').onclick=()=>changeBranch(false)}else bindLesson(id);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const l=lessons[current],correct=Number(b.dataset.answer)===l.correct;document.querySelectorAll('[data-answer]').forEach(x=>x.classList.remove('correct','incorrect'));b.classList.add(correct?'correct':'incorrect');$('.answer-feedback').textContent=(correct?'Exactly. ':'Not quite. ')+l.explanation;if(correct){completed[l.id]=true;try{localStorage.setItem('forklift-field-guide-v1',JSON.stringify(completed))}catch{}updateProgress();const n=$('#chapters .active .num');if(n)n.textContent='✓'}})}
function changeBranch(deleted){branchDeleted=deleted;$('#rows-2').textContent=deleted?'900':'1,000';$('#branch-2').classList.toggle('changed',deleted);$('#branch-2 .mini-rows i:last-child').classList.toggle('gone',deleted);$('#branch-caption-2').textContent=deleted?'100 rows deleted here only':'Restored from seed';$('#delete-rows').disabled=deleted;$('#reset-branch').disabled=!deleted;$('#branch-feedback').textContent=deleted?'Only experiment 03 changed. Its siblings and the seed still have 1,000 rows. Reset prepares a replacement from the checkpoint.':'Back to 1,000 rows. Reset discards this branch’s later changes by selecting a fresh generation. The other experiments were never touched.'}
configureLessons();
$('.skip').onclick=e=>{e.preventDefault();$('#content').focus();};
window.addEventListener('hashchange',()=>{render();$('#content').focus({preventScroll:true});window.scrollTo(0,0)});render();

if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
  register({name:'read_learning_progress',description:'Read the current lesson and knowledge checks completed on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({lesson:lessons[current].id,completed:lessons.filter(l=>completed[l.id]).map(l=>l.id),total:lessons.length})});
  register({name:'navigate_lesson',description:'Open a lesson in the field guide. Does not complete its knowledge check or change any real database.',inputSchema:{type:'object',properties:{lesson:{type:'string',enum:lessons.map(l=>l.id)}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||!lessons.some(l=>l.id===input.lesson))throw new Error('Unknown lesson');history.replaceState(null,'','#'+input.lesson);render();window.scrollTo(0,0);return{lesson:lessons[current].id,title:lessons[current].name}}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
